public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a set to store the visited n-tersections
    Set<Integer> visited = new HashSet<>();

    // Add the starting n-tersection to the set
    visited.add(start);

    // Create a queue to store the n-tersections to visit
    Queue<Integer> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue
    queue.offer(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current == end) {
            return "can be travelled";
        }

        // Loop through all the paths
        for (int[] path : paths) {
            // If the current n-tersection is the starting point of the path
            if (current == path[0]) {
                // Get the end point of the path
                int endPoint = path[1];

                // If the end point is not in the visited set, add it to the set and enqueue it
                if (!visited.contains(endPoint)) {
                    visited.add(endPoint);
                    queue.offer(endPoint);
                }
            }
        }
    }

    // If the algorithm reaches this point, it means that the starting n-tersection is not reachable from the ending n-tersection
    return "cannot be travelled";
}

