public double trimMean(int[] arr) {
    if (arr.length == 0) {
        return 0;
    }

    // Sort the array in ascending order
    Arrays.sort(arr);

    // Determine the index of the smallest 5% of elements
    int smallestIndex = (int) (arr.length * 0.05);

    // Determine the index of the largest 5% of elements
    int largestIndex = arr.length - (int) (arr.length * 0.05);

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = smallestIndex; i <= largestIndex; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the remaining elements
    double mean = (double) sum / (arr.length - 2 * (smallestIndex + 1));

    // Check if the mean is within 10^-5 of the true mean
    double epsilon = 0.00001;
    if (Math.abs(mean - (arr[arr.length / 2] / 2)) < epsilon) {
        return mean;
    } else {
        return -1;
    }
}

